/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

import net.civeira.phylax.feature.observe.store.ObsSpan;

/**
 * Performance problems in the stored spans of a batch, as events for the issues (kind PERFORMANCE):
 *
 * <ul>
 * <li><b>N+1 query</b>: at least {@code minRepeats} database calls with the same normalized
 * statement under the same parent span, adding up at least {@code minTotalMs}.</li>
 * <li><b>Slow operation</b>: a SERVER span slower than {@code slowMs} (0 disables it).</li>
 * </ul>
 * The fingerprint is forced (source, route and statement), so the same N+1 in a thousand traces is
 * one issue.
 */
public final class PerformanceDetector {

  public static final String N_PLUS_ONE = "N+1 query";
  public static final String SLOW = "Slow operation";
  public static final Set<String> TYPES = Set.of(N_PLUS_ONE, SLOW);

  private static final Pattern STRING = Pattern.compile("'(?:[^']|'')*'");
  private static final Pattern IN_LIST =
      Pattern.compile("(?i)\\bIN\\s*\\(\\s*\\?(?:\\s*,\\s*\\?)*\\s*\\)");
  private static final Pattern NUMBER = Pattern.compile("\\b\\d+(?:\\.\\d+)?\\b");
  private static final Pattern SPACES = Pattern.compile("\\s+");

  private PerformanceDetector() {}

  /** Statement without its literals: strings, numbers and lists of IN become {@code ?}. */
  public static String normalize(final String statement) {
    if (null == statement) {
      return "";
    }
    String result = STRING.matcher(statement).replaceAll("?");
    result = NUMBER.matcher(result).replaceAll("?");
    result = IN_LIST.matcher(result).replaceAll("IN (?)");
    result = SPACES.matcher(result).replaceAll(" ").trim();
    return result.length() > 300 ? result.substring(0, 299) + "…" : result;
  }

  public static List<ErrorEvent> detect(final List<ObsSpan> spans, final int minRepeats,
      final double minTotalMs, final long slowMs) {
    List<ErrorEvent> events = new ArrayList<>();
    if (null == spans || spans.isEmpty()) {
      return events;
    }
    Map<String, ObsSpan> byId = new LinkedHashMap<>();
    for (ObsSpan span : spans) {
      byId.put(span.traceId() + "/" + span.spanId(), span);
    }
    // N+1: database calls by trace, parent and statement
    Map<String, List<ObsSpan>> groups = new LinkedHashMap<>();
    for (ObsSpan span : spans) {
      if (!"CLIENT".equals(span.kind()) || null == span.attrs()
          || null == span.attrs().get("db.system")) {
        continue;
      }
      String statement = normalize(
          String.valueOf(first(span.attrs(), "db.query.text", "db.statement", span.name())));
      groups.computeIfAbsent(span.traceId() + "\n" + span.parentId() + "\n" + statement,
          k -> new ArrayList<>()).add(span);
    }
    for (Map.Entry<String, List<ObsSpan>> group : groups.entrySet()) {
      List<ObsSpan> calls = group.getValue();
      double total = calls.stream().mapToDouble(ObsSpan::durMs).sum();
      if (calls.size() < minRepeats || total < minTotalMs) {
        continue;
      }
      ObsSpan firstCall = calls.get(0);
      String statement = group.getKey().substring(group.getKey().lastIndexOf('\n') + 1);
      String route = route(byId, firstCall);
      events.add(event(firstCall, N_PLUS_ONE, calls.size() + " × " + statement + " in " + route,
          "n+1\n" + firstCall.src() + "\n" + route + "\n" + statement));
    }
    // Slow operations
    if (slowMs > 0) {
      for (ObsSpan span : spans) {
        if ("SERVER".equals(span.kind()) && span.durMs() > slowMs) {
          String route = String.valueOf(first(span.attrs(), "http.route", null, span.name()));
          events.add(event(span, SLOW, route + " slower than " + slowMs + " ms",
              "slow\n" + span.src() + "\n" + route));
        }
      }
    }
    return events;
  }

  /** The route of the SERVER span that holds a span (walking up its parents in the batch). */
  private static String route(final Map<String, ObsSpan> byId, final ObsSpan span) {
    ObsSpan current = span;
    for (int depth = 0; depth < 50 && null != current; depth++) {
      if ("SERVER".equals(current.kind())) {
        return String.valueOf(first(current.attrs(), "http.route", null, current.name()));
      }
      current = byId.get(current.traceId() + "/" + current.parentId());
    }
    ObsSpan parent = byId.get(span.traceId() + "/" + span.parentId());
    return null == parent ? span.name() : parent.name();
  }

  private static ErrorEvent event(final ObsSpan span, final String type, final String message,
      final String fingerprintKey) {
    return new ErrorEvent(span.src(), span.ts(), "WARN", type, message, null, span.traceId(),
        sha1(fingerprintKey), span.release(), EventContext.of(span.attrs()));
  }

  private static Object first(final Map<String, Object> attrs, final String key, final String other,
      final String fallback) {
    if (null != attrs && null != attrs.get(key)) {
      return attrs.get(key);
    }
    if (null != attrs && null != other && null != attrs.get(other)) {
      return attrs.get(other);
    }
    return fallback;
  }

  private static String sha1(final String value) {
    try {
      return HexFormat.of().formatHex(
          MessageDigest.getInstance("SHA-1").digest(value.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException ex) {
      throw new IllegalStateException(ex);
    }
  }
}
